ALTER TABLE offices_agenda_inteligente_orus ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view active offices" ON offices_agenda_inteligente_orus FOR SELECT USING (ativo = true); CREATE POLICY "Authenticated users can insert offices" ON offices_agenda_inteligente_orus FOR INSERT WITH CHECK (auth.uid() IS NOT NULL); CREATE POLICY "Users can update offices they created" ON offices_agenda_inteligente_orus FOR UPDATE USING (created_by_user_id = auth.uid()); CREATE POLICY "Users can delete offices they created" ON offices_agenda_inteligente_orus FOR DELETE USING (created_by_user_id = auth.uid());;
